<section class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h1 class="text-2xl font-bold text-slate-900">Daftar Ulang</h1><p class="mt-1 text-sm text-slate-500">Pantau pengajuan dan verifikasi sambungan kembali pelanggan.</p></div><?php if (Auth::isAdmin()): ?><a href="<?= e(url('/daftar-ulang/create')) ?>" class="inline-flex items-center justify-center rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-white shadow-lg shadow-blue-900/15 hover:bg-primary-dark">+ Pengajuan Baru</a><?php endif; ?></section>
<section class="rounded-2xl bg-white p-4 shadow-card sm:p-6"><div class="flex flex-wrap gap-2 border-b border-slate-100 pb-5"><a href="<?= e(url('/daftar-ulang')) ?>" class="filter-pill <?= $status === '' ? 'filter-pill-active' : '' ?>">Semua</a><?php foreach (['Pending','Disetujui','Ditolak'] as $option): ?><a href="<?= e(url('/daftar-ulang?status=' . rawurlencode($option))) ?>" class="filter-pill <?= $status === $option ? 'filter-pill-active' : '' ?>"><?= e($option) ?></a><?php endforeach; ?></div><div class="mt-6 overflow-hidden rounded-xl border border-slate-100"><?php if ($data['rows']): ?><div class="table-wrap"><table class="w-full min-w-[840px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">No. Registrasi</th><th class="px-5 py-3">Pelanggan</th><th class="px-5 py-3">Tanggal</th><th class="px-5 py-3">Biaya</th><th class="px-5 py-3">Status</th><th class="px-5 py-3 text-right">Aksi</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($data['rows'] as $row): ?><tr><td class="px-5 py-4 font-mono text-xs font-semibold text-primary"><?= e($row['no_registrasi']) ?></td><td class="px-5 py-4"><p class="font-semibold text-slate-800"><?= e($row['nama_pelanggan']) ?></p><p class="text-xs text-slate-500"><?= e($row['npa']) ?></p></td><td class="px-5 py-4 text-slate-600"><?= e(formatTanggalWaktu($row['tgl_permohonan'])) ?></td><td class="px-5 py-4 font-semibold text-slate-800"><?= e(formatRupiah($row['biaya_daftar_ulang'])) ?></td><td class="px-5 py-4"><span class="badge badge-<?= strtolower($row['status_verifikasi']) ?>"><?= e($row['status_verifikasi']) ?></span></td><td class="px-5 py-4 text-right"><a href="<?= e(url('/daftar-ulang/' . rawurlencode($row['no_registrasi']))) ?>" class="font-semibold text-primary hover:underline">Detail</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: $emptyTitle='Belum ada pengajuan daftar ulang'; $emptyText='Pengajuan baru akan di